def solve(grid):
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r,c)]
        while stack:
            x,y = stack.pop()
            if x<0 or x>=rows or y<0 or y>=cols:
                continue
            if visited[x][y] or grid[x][y]==0:
                continue
            visited[x][y] = True
            stack.append((x+1,y))
            stack.append((x-1,y))
            stack.append((x,y+1))
            stack.append((x,y-1))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count += 1
    return count

def solve(words, k):
    # Convert k to int if possible
    try:
        k = int(k)
    except Exception:
        return []
    if k <= 0:
        return []
    from collections import Counter
    freq = Counter(words)
    # Sort words by descending frequency then alphabetically
    sorted_words = sorted(freq.keys(), key=lambda w: (-freq[w], w))
    return sorted_words[:k]

