def solve(n):
    """Return the count of prime numbers strictly less than n.
    Uses Sieve of Eratosthenes up to n-1.
    """
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * n  # True for potential primes
    sieve[0:2] = b'\x00\x00'
    import math
    limit = int(math.isqrt(n - 1))
    for i in range(2, limit + 1):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start:n:step] = b'\x00' * ((n - start - 1) // step + 1)
    return sum(sieve)

