{"task_id": "T25", "code": "def solve(matrix):
    # Determinant of square matrix of integers. Empty matrix -> 1.
    n = len(matrix)
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    # Use recursion with expansion by first row
    def det(m):
        size = len(m)
        if size == 1:
            return m[0][0]
        if size == 2:
            return m[0][0]*m[1][1] - m[0][1]*m[1][0]
        total = 0
        for col, val in enumerate(m[0]):
            if val == 0:
                continue
            # build minor matrix
            minor = [row[:col] + row[col+1:] for row in m[1:]]
            sign = -1 if col % 2 else 1
