def solve(matrix):
    """Return the determinant of a square integer matrix.
    Empty matrix returns 1.
    Uses recursive Laplace expansion; suitable for small matrices.
    """
    n = len(matrix)
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    # Helper recursive function
    def det(m):
        size = len(m)
        if size == 1:
            return m[0][0]
