def solve(coins, amount):
    # DP for unbounded knapsack (coin change) to find minimum number of coins.
    # If amount is 0, answer is 0.
    if amount == 0:
        return 0
    # Initialize DP array with a sentinel larger than any possible answer.
    # Use amount+1 as sentinel because the max coins needed cannot exceed amount (using coin of value 1 if present).
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If using coin c leads to a better solution, update.
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != max_val else -1

