def solve(a, x):
    # Handle None or non-iterable a as empty list
    try:
        length = len(a)
    except Exception:
        return 0
    lo, hi = 0, length
    while lo < hi:
        mid = (lo + hi) // 2
        try:
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        except Exception:
            # Incompatible types, cannot determine order; default to 0
            return 0
    return lo

