def solve(meetings):
    # Filter out invalid entries: must be a sequence with at least two numeric elements and start <= end
    valid = []
    for m in meetings:
        if not isinstance(m, (list, tuple)):
            continue
        if len(m) < 2:
            continue
        start, end = m[0], m[1]
        # ensure they are numbers (int or float)
        if not isinstance(start, (int, float)) or not isinstance(end, (int, float)):
            continue
        if start <= end:
            valid.append((start, end))
    # Greedy: sort by end time, then start time
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in valid:
        if s >= current_end:
            count += 1
            current_end = e
    return count

