def solve(lst):
    """Flatten a nested structure containing integers.
    The input may be a list (or tuple) that contains integers or further nested
    lists/tuples. Returns a flat list of all integers in left‑to‑right order.
    Booleans are excluded (they are subclasses of int).
    """
    result = []
    def dfs(x):
        if isinstance(x, (list, tuple)):
            for item in x:
                dfs(item)
        else:
            if isinstance(x, int) and not isinstance(x, bool):
                result.append(x)
